function rrBureau(text,filename,override){if(override&&override!=='auto')return override;const x=(filename+' '+text.slice(0,1600)).toLowerCase();return /transunion/.test(x)?'TransUnion':/equifax/.test(x)?'Equifax':/experian/.test(x)?'Experian':'Not identified'}
function rrProfile(lines){const name=rrField(lines,['Consumer\\s*Name','Full\\s*Name','Report\\s*For','Prepared\\s*For','Personal\\s*Name']);const a=rrField(lines,['Current\\s*(?:Mailing\\s*)?Address','Mailing\\s*Address','Residential\\s*Address']);const p={};if(name&&/^[A-Za-z][A-Za-z\-' ]{3,75}$/.test(name)&&name.trim().split(/\s+/).length>=2)p.name=name.trim();if(a&&a.length<130)p.address=a.trim();const c=rrField(lines,['City']),st=rrField(lines,['State']),zip=rrField(lines,['ZIP(?:\\s*Code)?']);if(c&&c.length<65)p.city=c;if(st&&/^[A-Za-z]{2,20}$/.test(st))p.state=st;if(zip&&/^\d{5}/.test(zip))p.zip=zip.slice(0,5);const full=(a||'').match(/^(.+?\b(?:Street|St\.?|Ave\.?|Avenue|Road|Rd\.?|Boulevard|Blvd\.?|Lane|Ln\.?|Drive|Dr\.?|Court|Ct\.?|Way|Place|Pl\.?)\b(?:\s+(?:Apt|Apartment|Unit|Ste|Suite)\s*#?\w+)?)\s*,?\s+([A-Za-z][A-Za-z\s.'-]+?)\s*,?\s+([A-Z]{2})\s+(\d{5}(?:-\d{4})?)$/i);if(full){p.address=full[1].trim();p.city=full[2].trim();p.state=full[3];p.zip=full[4].slice(0,5)}return p}
function rrAccountAnchors(lines){const anchors=[];const head=/^(?:Account\s*Name|Creditor\s*Name|Company\s*Name|Collection\s*Agency|Collection\s*Company|Reported\s*By|Furnisher|Creditor)(?:\s*[:#：–-]\s*|\s+)(.+)$/i;const accountNameOnly=/^(?:Account\s*Name|Creditor\s*Name|Company\s*Name|Collection\s*Agency|Collection\s*Company|Reported\s*By|Furnisher|Creditor)$/i;for(let i=0;i<lines.length;i++){let name='';const m=lines[i].match(head);if(m)name=m[1]?.trim()||'';else if(accountNameOnly.test(lines[i])&&i+1<lines.length)name=lines[i+1];if(name&&!/^(?:Account|Balance|Payment|Date|Credit|Report|Status|Not available|None|N\/A)$/i.test(name)&&name.length>2&&name.length<90)anchors.push({index:i,name:rrCompany(name)});}if(!anchors.length){for(let i=0;i<lines.length;i++){const hasAccount=/^Account\s*(?:Number|#|No\.|ID)\s*[:#]/i.test(lines[i]);if(!hasAccount)continue;const before=lines.slice(Math.max(0,i-5),i).reverse().find(s=>/^[A-Za-z][A-Za-z0-9 .,&'/-]{3,70}$/.test(s)&&!/^(?:Account|Balance|Credit|Report|Payment|Date|Status|Original|Address|Consumer)/i.test(s));if(before)anchors.push({index:Math.max(0,i-3),name:rrCompany(before)})}}return anchors.filter((x,i)=>i===0||x.index!==anchors[i-1].index)}
function rrParseAccounts(text,sourceName,forcedBureau){const lines=rrLines(text);const bureau=rrBureau(text,sourceName,forcedBureau);const anchors=rrAccountAnchors(lines);const reportDate=rrDate(rrField(lines.slice(0,110),['Report\\s*Date','Date\\s*of\\s*Report','Report\\s*Generated','Generated\\s*On','Prepared\\s*On']));const entries=[];for(let n=0;n<anchors.length;n++){const a=anchors[n],end=anchors[n+1]?.index??lines.length;const seg=lines.slice(a.index,Math.min(end,a.index+70));const account=rrLast4(rrField(seg,['Account\\s*(?:Number|No\\.?|#|ID|Reference)','Acct\\s*(?:No\\.?|Number|#)']));const balance=rrNum(rrField(seg,['(?:Current\\s*)?Balance','Amount\\s*Owed','Total\\s*Balance','Outstanding\\s*Balance']));const limit=rrNum(rrField(seg,['Credit\\s*Limit','Credit\\s*Line','Limit']));const originalCreditor=rrField(seg,['Original\\s*Creditor','Original\\s*Lender']);const status=rrField(seg,['Account\\s*Status','Payment\\s*Status','Status','Current\\s*Status']);const accountType=rrField(seg,['Account\\s*Type','Type\\s*of\\s*Account','Industry\\s*Type']);const pastDue=rrNum(rrField(seg,['Past\\s*Due(?:\\s*Amount)?','Amount\\s*Past\\s*Due']));const opened=rrDate(rrField(seg,['Date\\s*Opened','Opened','Date\\s*Account\\s*Opened']));const firstMissed=rrDate(rrField(seg,['Date\\s*of\\s*First\\s*Delinquency','First\\s*Delinquency','Date\\s*of\\s*First\\s*Default','First\\s*Missed\\s*Payment']));const lastReported=rrDate(rrField(seg,['Date\\s*(?:Last\\s*)?Reported','Last\\s*Reported','Reported\\s*On','Date\\s*Updated','Last\\s*Updated']));const paymentHistory=rrField(seg,['Payment\\s*History','Payment\\s*Rating']);const complete=[a.name,status,accountType,paymentHistory,seg.slice(0,16).join(' ')].join(' ').toLowerCase();let type='Other';if(/collection|debt buyer|recovery/.test(complete))type='Collection';else if(/charge.?off|charged.?off/.test(complete))type='Charge-off';else if(/repossess/.test(complete))type='Repossession';else if(/late|delinquen|30 days|60 days|90 days/.test(complete))type='Late payments';const score=[!!a.name,!!account,!!status,!!balance,!!limit].filter(Boolean).length;const id='r'+entries.length+'-'+Math.random().toString(36).slice(2,7);entries.push({id,company:a.name,originalCreditor,account,balance,limit,status,accountType,pastDue,opened,firstMissed,lastReported,reportDate,paymentHistory,type,bureau,source:sourceName,confidence:score>=4?'Good':score>=2?'Partial':'Low',raw:seg.slice(0,32).join('\n')});}return{bureau,reportDate,profile:rrProfile(lines.slice(0,140)),entries,lines:lines.length,hasText:text.trim().length>0};}
function rrHeuristic(a,all){const hints=[];const st=(a.status+' '+a.accountType+' '+a.paymentHistory).toLowerCase();if(a.type==='Collection'){hints.push({kind:'Review',title:'Check the collection details',body:'Compare the amount, creditor name, ownership and first-delinquency date with your records. A collection entry is not automatically an error.',issue:'balance'});hints.push({kind:'Option',title:'Debt validation request',body:'If you received a collector’s validation notice, review its dispute-by date. A validation request and a credit-bureau dispute are different processes.',issue:''})}else if(a.type==='Charge-off')hints.push({kind:'Review',title:'Check the charge-off reporting',body:'A charge-off means the lender wrote the debt off in its accounting. It does not by itself prove the balance is wrong or the debt is canceled.',issue:'balance'});if(/late|delinquen|30|60|90|120|past due/.test(st)||Number(a.pastDue)>0)hints.push({kind:'Review',title:'Verify payment history',body:'Check every late month against payment receipts and statements. A late mark should only be disputed if a specific date or status is inaccurate.',issue:'late'});if(/paid|settled|closed/.test(st)&&Number(a.balance)>0)hints.push({kind:'Check',title:'Balance and status need a closer look',body:'The status mentions paid, settled or closed but a balance is shown. Some closed accounts legitimately retain a balance. Verify the exact status and amount.',issue:'paid'});const balance=Number(a.balance),limit=Number(a.limit);if(a.limit&&limit>0&&a.balance&&balance>=0)hints.push({kind:'Education',title:'Credit utilization: '+Math.round(balance/limit*100)+'%',body:'This is the balance divided by the limit. High utilization can affect scoring but is not itself a reporting error or grounds for deletion.',issue:''});if(a.firstMissed)hints.push({kind:'Check',title:'First delinquency date',body:'Check the first missed-payment date against original statements. A sale to a collector does not create a new first delinquency date.',issue:'date'});const matches=all.filter(x=>x.id!==a.id&&x.company.toLowerCase().replace(/[^a-z0-9]/g,'')===a.company.toLowerCase().replace(/[^a-z0-9]/g,'')&&(!a.account||!x.account||a.account===x.account));if(matches.some(x=>x.bureau!==a.bureau&&x.balance!==a.balance&&x.balance!==''&&a.balance!==''))hints.push({kind:'Compare',title:'Balances differ across reports',body:'A matching creditor has a different balance on another bureau’s report. Reporting dates can differ. Compare the dates and your records before identifying an error.',issue:'balance'});if(matches.some(x=>x.bureau===a.bureau))hints.push({kind:'Compare',title:'Two similar entries appear',body:'Check whether these are separate legal accounts, or an original creditor and collector reporting the same debt. Similar entries do not automatically mean unlawful duplicates.',issue:'duplicate'});if(!hints.length)hints.push({kind:'Check',title:'Compare the report to your records',body:'Verify the owner, account reference, balance, status and dates. If all are accurate, there may be nothing to dispute.',issue:''});return hints;}
function rrExplain(a){let intro=`${a.company} is listed on ${a.bureau==='Not identified'?'an unidentified bureau report':a.bureau}. `;intro+=a.account?`The visible account reference ends in ${a.account}. `:'The account reference was not reliably extracted. ';if(a.balance!=='')intro+=`The reported balance is ${rrMoney(a.balance)}. `;if(a.status)intro+=`Its reported status is “${a.status}”. `;if(a.type==='Collection')intro+='A collection generally means a collector or debt buyer reports a debt. That is not proof the debt is valid or invalid. ';else if(a.type==='Charge-off')intro+='A charge-off is an accounting classification, not automatic debt forgiveness. ';else if(a.type==='Late payments')intro+='Late marks describe past payment timing, and must be compared with your actual payment records. ';if(a.limit)intro+=`The reported credit limit is ${rrMoney(a.limit)}. `;intro+='These are details extracted from the document, not verified findings. Check against the original report and supporting records.';return intro;}
