function rrQueueCanvas(canvas,name){
 const a=reportReader.ai;
 const maxEdge=2150,original=Math.max(canvas.width,canvas.height),ratio=Math.min(1,maxEdge/original);
 const out=document.createElement('canvas');out.width=Math.max(1,Math.round(canvas.width*ratio));out.height=Math.max(1,Math.round(canvas.height*ratio));
 const ctx=out.getContext('2d',{alpha:false});ctx.fillStyle='#fff';ctx.fillRect(0,0,out.width,out.height);ctx.drawImage(canvas,0,0,out.width,out.height);
 let data='';for(const quality of [.88,.76,.62,.5]){data=out.toDataURL('image/jpeg',quality);if(data.length<1500000)break}
 if(data.length>=1600000){const shrink=document.createElement('canvas');shrink.width=Math.floor(out.width*.75);shrink.height=Math.floor(out.height*.75);shrink.getContext('2d').drawImage(out,0,0,shrink.width,shrink.height);data=shrink.toDataURL('image/jpeg',.65);shrink.width=shrink.height=0}
 out.width=out.height=0;
 if(data.length>1600000)throw Error('Screenshot is too large for AI. Crop the page into smaller screenshots.');
 a.images.push({name,data});return data;
}
async function rrAiCaptureImage(file,name){
 if(!/image\//.test(file.type)&&!/\.(png|jpe?g|webp|heic)$/i.test(name))return;
 const url=URL.createObjectURL(file);try{
  const img=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('Image could not be decoded. Export as PNG or JPEG.'));im.src=url});
  const cv=document.createElement('canvas');cv.width=img.naturalWidth;cv.height=img.naturalHeight;cv.getContext('2d',{alpha:false}).drawImage(img,0,0);rrQueueCanvas(cv,name);cv.width=cv.height=0;
 }finally{URL.revokeObjectURL(url)}
}
function rrAiIngestProfile(raw){
 if(!raw||typeof raw!=='object')return true;
 const p={};for(const key of ['name','address','city','state','zip'])p[key]=rrShort(raw[key]||'',key==='address'?120:85);
 const old=String(reportReader.profile.name||'').replace(/\W/g,'').toLowerCase(),incoming=p.name.replace(/\W/g,'').toLowerCase();
 if(old&&incoming&&old!==incoming){reportReader.ai.error='The AI found a different report holder than an earlier upload. Clear the session and scan each person separately.';return false}
 for(const k of ['name','address','city','state','zip'])if(p[k]&&!reportReader.profile[k])reportReader.profile[k]=p[k];return true;
}
function rrAiMergeResults(results){
 const merged={summary:results.map(x=>x.summary||'').filter(Boolean).join(' '),answer:results.map(x=>x.answer||'').filter(Boolean).join(' '),accounts:[],cautions:[...new Set(results.flatMap(x=>x.cautions||[]))],profile:{}};
 for(const item of results){for(const k of ['name','address','city','state','zip'])if(!merged.profile[k]&&item.profile?.[k])merged.profile[k]=item.profile[k];for(const a of item.accounts||[]){const n=String(a.company||'').toLowerCase().replace(/[^a-z0-9]/g,'');if(!n)continue;const last=rrLast4(a.accountLast4||'');const bureau=String(a.bureau||'').toLowerCase();const existing=merged.accounts.find(x=>(String(x.company||'').toLowerCase().replace(/[^a-z0-9]/g,'')===n||!!(last&&rrLast4(x.accountLast4)===last))&&String(x.bureau||'').toLowerCase()===bureau&&(!last||!x.accountLast4||rrLast4(x.accountLast4)===last));if(existing){for(const [k,v] of Object.entries(a))if(!existing[k]&&v)existing[k]=v;continue}merged.accounts.push(a)}}
 return merged;
}
async function rrAiRun(mode){
 const a=reportReader.ai;
 if(a.busy)return;
 if(!a.endpoint.trim()||!/^https:\/\/[^\s/]+(?:\/[^\s]*)?$/i.test(a.endpoint.trim())){a.error='Set the HTTPS backend address under AI connection settings.';render();return}
 if(!a.accessCode.trim()){a.error='Open AI connection settings and enter your private access code—not your OpenAI API key.';render();return}
 if(!a.consent){a.error='Check the consent box to authorize sending this report to your AI service.';render();return}
 const useImages=a.includeImages?a.images:[];
 if(!a.payload.trim()&&(reportReader.reportText||useImages.length))rrAiPrepare();
 if(!a.payload.trim()&&!useImages.length){a.error='Upload screenshots, a PDF, or paste report text first.';render();return}
 if(mode==='ask'&&!a.question.trim()){a.error='Type your question first.';render();return}
 const batches=[];
 if(useImages.length){for(let i=0;i<useImages.length;i+=2)batches.push(useImages.slice(i,i+2))}else batches.push([]);
 a.busy=true;a.error='';a.status=`Starting ${batches.length} AI image batch${batches.length===1?'':'es'}…`;
 // Make a copy of the latest typed fields before rendering.
 a.payload=document.getElementById('readerAiPayload')?.value??a.payload;
 a.question=document.getElementById('readerAiQuestion')?.value??a.question;
 render();const responses=[];
 try{
  for(let i=0;i<batches.length;i++){
   if(reportReader.cancel)break;
   a.status=`AI reading batch ${i+1} of ${batches.length} (${Math.min(useImages.length,(i+1)*2)} of ${useImages.length||0} images)…`;
   const el=document.getElementById('readerAiStatus');if(el)el.textContent=a.status;
   const text=(i===0?a.payload.slice(0,40000):`Continue reading this same person's next screenshot(s). Credit report holder: ${reportReader.profile.name||'not established'}. Extract only information from the attached new image(s).`);
   const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),65000);
   let response;
   try{response=await fetch(a.endpoint.trim(),{method:'POST',mode:'cors',cache:'no-store',credentials:'omit',signal:controller.signal,headers:{'Content-Type':'application/json','X-Access-Code':a.accessCode},body:JSON.stringify({mode,text,question:mode==='ask'?a.question.trim().slice(0,900):'',images:batches[i].map(x=>x.data),consent:true})})}finally{clearTimeout(timeout)}
   const data=await response.json().catch(()=>({error:`Server returned HTTP ${response.status}. Try again later.`}));if(!response.ok)throw Error(`Batch ${i+1}: ${data.error||`HTTP ${response.status}`}`);
   responses.push(data);
  }
  if(!responses.length)throw Error('No screenshots were analyzed.');
  const merged=rrAiMergeResults(responses);
  if(mode==='ask'){a.answer=rrShort(merged.answer||merged.summary||'No answer returned',6000);a.status='AI answered. Cross-check the document before relying on its findings.'}
  else{
   if(!rrAiIngestProfile(merged.profile))throw Error('Mixed report holders detected. Clear the Reader and keep each person separate.');
   a.result=merged;
   const n=rrAiReviewImport(true);
   a.status=`AI scanned ${useImages.length} screenshot(s) in ${responses.length} batch(es). ${merged.accounts.length} account finding(s); ${n} new entries staged automatically for review and autofill.`;
  }
 }catch(e){a.error=String(e.message||e).slice(0,420);a.status=responses.length?`Some images analyzed (${responses.length} of ${batches.length} batches). You can retry the remaining screenshots.`:'No changes saved; try another screenshot or check the backend connection.';
  // Preserve successful partial analysis instead of discarding it.
  if(mode==='analyze'&&responses.length){const m=rrAiMergeResults(responses);if(rrAiIngestProfile(m.profile)){a.result=m;rrAiReviewImport(true)}}
 }finally{a.busy=false;render()}
}
function rrAiReviewImport(silent=false){
 const r=reportReader,items=r.ai.result?.accounts||[];
 if(!items.length){if(!silent)toast('AI did not identify any accounts');return 0}
 let n=0,enhanced=0;
 for(const x of items){if(!x.company||/^(unknown|unidentified|not provided)/i.test(x.company))continue;
 const bureau=BUREAUS.includes(x.bureau)?x.bureau:'Not identified';const acc=rrLast4(x.accountLast4||'');
 const cleaned=String(x.company).toLowerCase().replace(/[^a-z0-9]/g,'');
 const existing=r.accounts.find(z=>z.bureau===bureau&&((acc&&z.account===acc)||String(z.company).toLowerCase().replace(/[^a-z0-9]/g,'')===cleaned)&&(!acc||!z.account||acc===z.account));
 const aiReview={explanation:x.explanation,suggestedPath:x.suggestedPath,verificationQuestions:x.verificationQuestions,sourceQuote:x.sourceQuote};
 const extra={company:rrShort(x.company,85),account:acc,balance:rrNum(x.balance),limit:rrNum(x.creditLimit),status:rrShort(x.status,125),originalCreditor:rrShort(x.originalCreditor,100),accountType:rrShort(x.accountType,80),pastDue:rrNum(x.pastDue),opened:rrDate(x.dateOpened),firstMissed:rrDate(x.firstDelinquency),lastReported:rrDate(x.lastReported),paymentHistory:rrShort(x.paymentHistory,120)};
 if(existing){if(!existing.corrected)for(const [k,v] of Object.entries(extra))if(!existing[k]&&v)existing[k]=v;existing.aiReview=aiReview;existing.confidence='AI review — verify';r.selected.add(existing.id);enhanced++;continue}
 const id='ai-'+Date.now()+'-'+Math.random().toString(36).slice(2,9);
 const type=['Collection','Charge-off','Repossession','Late payments','Other','Inquiry','Medical collection','Not my account','Personal information'].includes(x.type)?x.type:'Other';
 const acct={id,...extra,reportDate:'',type,bureau,source:'AI screenshot review (not independently verified)',confidence:'AI review — verify',raw:x.sourceQuote||'',aiReview};
 r.accounts.push(acct);r.review[id]={issue:'',note:'',verified:false};r.selected.add(id);n++;
 }
 r.status=`AI found ${n} new account(s), enhanced ${enhanced}. Review the original screenshots before importing. No dispute allegations were added.`;
 if(!silent){render();toast('AI fields staged automatically — review and autofill')}
 return n;
}
function rrAiFastAutofill(){
 const r=reportReader;
 if(!r.accounts.length){toast('Scan some screenshots first');return}
 const checkbox=document.getElementById('readerImportConfirm');
 if(!checkbox){toast('Scroll to Transfer to case and choose where to import');return}
 if(!confirm(`Autofill ${r.selected.size} selected account(s) into a draft client case? Confirm that you checked the displayed account names, balances and statuses against the original screenshots. No dispute allegation will be asserted automatically.`))return;
 checkbox.checked=true;
 const profileBox=document.getElementById('readerProfileConfirm');if(profileBox)profileBox.checked=true;
 rrImport();
}
